import * as THREE from 'three/webgpu';
import { texture, uv, vec2, MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  // Geometry sized to source rect aspect ratio (512/320 = 1.6)
  const aspect = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // Load texture (assumed cached / synchronous)
  const loadedTexture = ctx.textureLoader.load(config.imageUrl);

  // Set up material with TSL texture node (full UV, no atlas offset – source rect is the full image)
  const material = new MeshBasicNodeMaterial();
  const textureNode = texture(loadedTexture).uv(uv());
  material.mapNode = textureNode;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position.x, config.position.y, config.position.z);
  mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // Billboard toward camera every frame
  const updateHandler = () => {
    mesh.lookAt(ctx.camera.position);
  };

  mesh.userData.handlers = {
    update: updateHandler
  };

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return mesh;
}
